  select id from countries where slug = 'iran' limit 1
), upserted_city as (
  insert into cities (
    country_id, slug, name_az, name_en, name_ru, lat, lng, population,
    short_desc_en, description_en, source, source_url, license, attribution_text, last_synced_at
  )
  select
    country_ref.id, 'tehran', 'Tehran', 'Tehran', 'Тегеран',
    35.6892, 51.389, 9033000,
    'Tehran is the capital and largest city of Iran. It is also the capital of Tehran province and the administrative center for Tehran County and its Central District. With a population of around 9 million in the city, and 16.8 million in the metropolitan area, Tehran is the most populous city in Iran and West Asia, the second-largest metropolitan area in the Middle East after Cairo, and the 24th-most-populous metropolitan area in the world. Greater Tehran includes several municipalities, including Karaj, Eslamshahr, Shahriar, Qods, Malard, Golestan, Varamin, Pakdasht, Qarchak, Nasimshahr, Parand, Pardis, Andisheh and Fardis.', 'Tehran is the capital and largest city of Iran. It is also the capital of Tehran province and the administrative center for Tehran County and its Central District. With a population of around 9 million in the city, and 16.8 million in the metropolitan area, Tehran is the most populous city in Iran and West Asia, the second-largest metropolitan area in the Middle East after Cairo, and the 24th-most-populous metropolitan area in the world. Greater Tehran includes several municipalities, including Karaj, Eslamshahr, Shahriar, Qods, Malard, Golestan, Varamin, Pakdasht, Qarchak, Nasimshahr, Parand, Pardis, Andisheh and Fardis.',
    'wikipedia', 'https://en.wikipedia.org/wiki/Tehran', 'CC BY-SA', 'Wikipedia contributors, Tehran', now()
  from country_ref
  on conflict (country_id, slug) do update set
    name_az = excluded.name_az,
    name_en = excluded.name_en,
    name_ru = excluded.name_ru,
    lat = excluded.lat,
    lng = excluded.lng,
    population = excluded.population,
    short_desc_en = excluded.short_desc_en,
    description_en = excluded.description_en,
    source = excluded.source,
    source_url = excluded.source_url,
    license = excluded.license,
    attribution_text = excluded.attribution_text,
    last_synced_at = now()
  returning id, country_id
